// Open Legend Unofficial — Deal Damage (Regular + Lethal)
// Prompts for regular + lethal damage and applies both to every TARGETED token.
const { DialogV2 } = foundry.applications.api;
const ol = game.openlegend;
if ( !ol?.applyDamageToToken || !ol?.applyLethalDamageToToken ) {
  ui.notifications?.error("Open Legend Unofficial damage helpers are unavailable.");
  return;
}
const targets = [...(game.user?.targets ?? [])];
if ( !targets.length ) {
  ui.notifications?.warn("Target one or more tokens first (use the targeting tool), then run this macro.");
  return;
}
const names = targets.map(t => t.name ?? t.actor?.name ?? "token").join(", ");
const esc = s => foundry.utils.escapeHTML?.(s) ?? s;
const content = `
  <div class="ol-deal-damage">
    <p>Deal damage to <strong>${esc(names)}</strong> (${targets.length} target${targets.length === 1 ? "" : "s"}).</p>
    <div class="form-group">
      <label>Regular damage</label>
      <input type="number" name="regular" value="0" min="0" step="1" autofocus/>
    </div>
    <div class="form-group">
      <label>Lethal damage</label>
      <input type="number" name="lethal" value="0" min="0" step="1"/>
    </div>
    <div class="form-group">
      <label>Damage type (optional)</label>
      <input type="text" name="type" placeholder="e.g. Fire"/>
    </div>
    <p class="hint">Lethal damage reduces both current and maximum HP; regular damage reduces current HP only.</p>
  </div>`;
const result = await DialogV2.wait({
  window: { title: "Deal Damage" },
  classes: ["openlegend"],
  content,
  rejectClose: false,
  buttons: [
    { action: "deal", label: "Deal Damage", icon: "fas fa-burst", default: true,
      callback: (event, button, dialog) => {
        const root = dialog.element;
        return {
          regular: Math.max(0, Math.floor(Number(root.querySelector('[name="regular"]')?.value) || 0)),
          lethal: Math.max(0, Math.floor(Number(root.querySelector('[name="lethal"]')?.value) || 0)),
          type: String(root.querySelector('[name="type"]')?.value ?? "").trim()
        };
      } },
    { action: "cancel", label: "Cancel", icon: "fas fa-times" }
  ]
});
if ( !result || (typeof result !== "object") ) return;
const { regular, lethal, type } = result;
if ( (regular <= 0) && (lethal <= 0) ) {
  ui.notifications?.info("No damage entered.");
  return;
}
for ( const token of targets ) {
  const uuid = token.document?.uuid ?? token.actor?.uuid;
  if ( !uuid ) continue;
  const applyId = `macro-${foundry.utils.randomID?.() ?? uuid}`;
  if ( lethal > 0 ) await ol.applyLethalDamageToToken(uuid, lethal, type, applyId);
  if ( regular > 0 ) await ol.applyDamageToToken(uuid, regular, type, applyId);
}
